from __future__ import annotations
from pathlib import Path

ENGINE_TEMPLATES = {'Execution/AsyncTradeExecutor.mqh': '#pragma once\n#include <Trade/Trade.mqh>\n\nclass CAsyncTradeExecutor\n{\nprivate:\n   CTrade m_trade;\n   ulong  m_pending_tickets[];\n   int    m_magic;\n   int    m_retry_limit;\n\n   bool IsPending(const ulong ticket)\n   {\n      for(int i = 0; i < ArraySize(m_pending_tickets); ++i)\n         if(m_pending_tickets[i] == ticket)\n            return true;\n      return false;\n   }\n\n   void AddPending(const ulong ticket)\n   {\n      if(IsPending(ticket))\n         return;\n      int n = ArraySize(m_pending_tickets);\n      ArrayResize(m_pending_tickets, n + 1);\n      m_pending_tickets[n] = ticket;\n   }\n\n   void RemovePending(const ulong ticket)\n   {\n      int n = ArraySize(m_pending_tickets);\n      for(int i = 0; i < n; ++i)\n      {\n         if(m_pending_tickets[i] == ticket)\n         {\n            for(int j = i; j < n - 1; ++j)\n               m_pending_tickets[j] = m_pending_tickets[j + 1];\n            ArrayResize(m_pending_tickets, n - 1);\n            return;\n         }\n      }\n   }\n\npublic:\n   CAsyncTradeExecutor() : m_magic(0), m_retry_limit(2) {}\n\n   void Configure(const int magic, const int retry_limit = 2)\n   {\n      m_magic = magic;\n      m_retry_limit = retry_limit;\n      m_trade.SetExpertMagicNumber(m_magic);\n      m_trade.SetAsyncMode(true);\n   }\n\n   bool BuyFast(const double lots, const string symbol)\n   {\n      m_trade.SetAsyncMode(true);\n      return m_trade.Buy(lots, symbol);\n   }\n\n   bool SellFast(const double lots, const string symbol)\n   {\n      m_trade.SetAsyncMode(true);\n      return m_trade.Sell(lots, symbol);\n   }\n\n   bool ClosePositionFast(const ulong ticket)\n   {\n      if(ticket == 0 || IsPending(ticket))\n         return false;\n      m_trade.SetAsyncMode(true);\n      bool sent = m_trade.PositionClose(ticket);\n      if(sent)\n         AddPending(ticket);\n      return sent;\n   }\n\n   bool ClosePositionFallbackSync(const ulong ticket)\n   {\n      if(ticket == 0)\n         return false;\n      m_trade.SetAsyncMode(false);\n      bool ok = m_trade.PositionClose(ticket);\n      m_trade.SetAsyncMode(true);\n      if(ok)\n         RemovePending(ticket);\n      return ok;\n   }\n\n   void OnTradeTransaction(\n      const MqlTradeTransaction& trans,\n      const MqlTradeRequest& request,\n      const MqlTradeResult& result\n   )\n   {\n      if(trans.type == TRADE_TRANSACTION_DEAL_ADD || trans.type == TRADE_TRANSACTION_HISTORY_ADD)\n      {\n         if(trans.position > 0)\n            RemovePending(trans.position);\n      }\n   }\n\n   int PendingCount() const\n   {\n      return ArraySize(m_pending_tickets);\n   }\n};\n', 'Execution/BasketCloseEngine.mqh': '#pragma once\n#include "AsyncTradeExecutor.mqh"\n\nclass CBasketCloseEngine\n{\nprivate:\n   CAsyncTradeExecutor* m_exec;\n   int m_magic;\n\npublic:\n   CBasketCloseEngine() : m_exec(NULL), m_magic(0) {}\n\n   void Configure(CAsyncTradeExecutor &exec, const int magic)\n   {\n      m_exec = &exec;\n      m_magic = magic;\n   }\n\n   int CloseBasketFast(const string symbol)\n   {\n      if(m_exec == NULL)\n         return 0;\n\n      int sent = 0;\n      for(int i = PositionsTotal() - 1; i >= 0; --i)\n      {\n         ulong ticket = PositionGetTicket(i);\n         if(!PositionSelectByTicket(ticket)) continue;\n         if(PositionGetString(POSITION_SYMBOL) != symbol) continue;\n         if((int)PositionGetInteger(POSITION_MAGIC) != m_magic) continue;\n         if(m_exec.ClosePositionFast(ticket))\n            sent++;\n      }\n      return sent;\n   }\n\n   int CloseSideFast(const string symbol, const ENUM_POSITION_TYPE side, const bool only_losing)\n   {\n      if(m_exec == NULL)\n         return 0;\n\n      int sent = 0;\n      for(int i = PositionsTotal() - 1; i >= 0; --i)\n      {\n         ulong ticket = PositionGetTicket(i);\n         if(!PositionSelectByTicket(ticket)) continue;\n         if(PositionGetString(POSITION_SYMBOL) != symbol) continue;\n         if((int)PositionGetInteger(POSITION_MAGIC) != m_magic) continue;\n         if((ENUM_POSITION_TYPE)PositionGetInteger(POSITION_TYPE) != side) continue;\n         if(only_losing && PositionGetDouble(POSITION_PROFIT) >= 0) continue;\n         if(m_exec.ClosePositionFast(ticket))\n            sent++;\n      }\n      return sent;\n   }\n};\n', 'Risk/GridRiskGuard.mqh': '#pragma once\n\nclass CGridRiskGuard\n{\nprivate:\n   double m_start_equity;\n   double m_freeze_dd;\n   double m_max_dd;\n   int    m_max_levels;\n\npublic:\n   CGridRiskGuard() : m_start_equity(0), m_freeze_dd(0.0), m_max_dd(0.0), m_max_levels(0) {}\n\n   void Configure(const double freeze_dd, const double max_dd, const int max_levels)\n   {\n      m_freeze_dd = freeze_dd;\n      m_max_dd = max_dd;\n      m_max_levels = max_levels;\n      if(m_start_equity <= 0)\n         m_start_equity = AccountInfoDouble(ACCOUNT_EQUITY);\n   }\n\n   double DDPercent()\n   {\n      double equity = AccountInfoDouble(ACCOUNT_EQUITY);\n      if(m_start_equity <= 0)\n         m_start_equity = equity;\n      if(m_start_equity <= 0)\n         return 0.0;\n      return MathMax(0.0, (m_start_equity - equity) / m_start_equity * 100.0);\n   }\n\n   bool Freeze() { return DDPercent() >= m_freeze_dd; }\n   bool Stop()   { return DDPercent() >= m_max_dd; }\n   bool LevelAllowed(const int current_levels) { return current_levels < m_max_levels; }\n};\n', 'State/PersistentStateStore.mqh': '#pragma once\n\nclass CPersistentStateStore\n{\nprivate:\n   string m_prefix;\n\npublic:\n   CPersistentStateStore() : m_prefix("EA") {}\n\n   void Configure(const string prefix)\n   {\n      m_prefix = prefix;\n   }\n\n   bool SaveDouble(const string key, const double value)\n   {\n      return GlobalVariableSet(m_prefix + "." + key, value) > 0;\n   }\n\n   double LoadDouble(const string key, const double fallback = 0.0)\n   {\n      string name = m_prefix + "." + key;\n      if(!GlobalVariableCheck(name))\n         return fallback;\n      return GlobalVariableGet(name);\n   }\n\n   bool SaveInt(const string key, const int value)\n   {\n      return SaveDouble(key, (double)value);\n   }\n\n   int LoadInt(const string key, const int fallback = 0)\n   {\n      return (int)LoadDouble(key, fallback);\n   }\n};\n', 'Telemetry/StructuredLogger.mqh': '#pragma once\n\nclass CStructuredLogger\n{\nprivate:\n   string m_name;\n\npublic:\n   CStructuredLogger() : m_name("EA") {}\n\n   void Configure(const string name)\n   {\n      m_name = name;\n   }\n\n   void Info(const string event_name, const string message)\n   {\n      Print("{\\"level\\":\\"INFO\\",\\"ea\\":\\"", m_name, "\\",\\"event\\":\\"", event_name, "\\",\\"message\\":\\"", message, "\\"}");\n   }\n\n   void Warn(const string event_name, const string message)\n   {\n      Print("{\\"level\\":\\"WARN\\",\\"ea\\":\\"", m_name, "\\",\\"event\\":\\"", event_name, "\\",\\"message\\":\\"", message, "\\"}");\n   }\n};\n'}

def write_engine_templates(include_root: str | Path, overwrite: bool = False) -> list[str]:
    base = Path(include_root)
    written: list[str] = []
    for rel, content in ENGINE_TEMPLATES.items():
        path = base / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists() and not overwrite:
            continue
        path.write_text(content, encoding="utf-8")
        written.append(str(path))
    return written
